import type { ReactNode } from 'react'
import { Pic } from './Pic'

export type SceneLabel = { title: string; text?: string | null; x: number; y: number }

/**
 * The region's first screen. With the admin's «Картинка первого экрана» (Илья, 20.10: our house and a fan of the
 * region's scenes around it, generated by Промты/lark/первый-экран-регион-остров.md v2): the words and numbers on
 * the left, the picture on the right on a matching dark stage, the scene labels from the admin over it (positions in
 * percent of the whole square picture). Without it: a photo of a house beside the words, as before.
 */
export function RegionHero({
  name,
  tagline,
  intro,
  scenes,
  photo,
  facts,
  actions,
}: {
  name: string
  tagline?: string | null
  intro?: string | null
  scenes?: { src: string; alt: string; labels: SceneLabel[] }
  photo?: { src: string; phone?: string; alt: string }
  facts: { value: string; label: string }[]
  actions: ReactNode
}) {
  return (
    <section className={`rh ${scenes ? 'rh--scenes' : ''}`} aria-labelledby="rh-title">
      <div className="rh__text">
        <p className="rh__eyebrow">Регион</p>
        <h1 className="rh__title" id="rh-title">
          {name}
        </h1>
        {tagline && <p className="rh__tag">{tagline}</p>}
        <div className="rh__facts">
          {facts.map((x) => (
            <div key={x.label}>
              <b>{x.value}</b>
              <span>{x.label}</span>
            </div>
          ))}
        </div>
        {intro && <p className="rh__intro">{intro}</p>}
        <div className="btns">{actions}</div>
      </div>

      {scenes ? (
        // the picture is square with an empty dark band on top: the band is cut off (design.css → .rh__pic)
        <figure className="rh__pic">
          <div className="rh__square">
            {/* the first screen's main picture: loaded at once, not lazily */}
            <img src={scenes.src} alt={scenes.alt} fetchPriority="high" decoding="async" />
            {scenes.labels.map((l) => (
              <span key={l.title} className="rh__label" style={{ left: `${l.x}%`, top: `${l.y}%` }}>
                <b>{l.title}</b>
                {l.text && <i>{l.text}</i>}
              </span>
            ))}
          </div>
          <figcaption>Иллюстрация</figcaption>
        </figure>
      ) : (
        photo && (
          <div className="rh__photo">
            <Pic src={photo.src} phone={photo.phone} alt={photo.alt} priority />
          </div>
        )
      )}
    </section>
  )
}
